`def group_entities(self, prediction_results_list: List[Dict] ) -> List[RecordDataResponse]:
        final_prediction_list = []

        # Group the prediction list by the last 3 characters of the tag
        # and group the results appropriately
        # B-PER-TAG -> TAG
        # B-PER -> PER
        tmp_dict = defaultdict(list)
        added_index = 0
        prev_index = 0
        for index, entity in enumerate(prediction_results_list):
            try:
                if entity['entity_group'].startswith("B") and \
                        prediction_results_list[index + 1]['entity_group'].startswith("I"):
                    tmp_dict[index].append(entity)
                    added_index = index
                elif entity['entity_group'].startswith("I"):
                    if (1 == abs(added_index - index)) or (1 == abs(prev_index - index)):
                        tmp_dict[added_index].append(entity)
                        prev_index = index
                else:
                    tmp_dict[index].append(entity)
            except IndexError:
                tmp_dict[index].append(entity)

        # Flatten the sub-lists
        final_grouped_list = list(map(list, map(itertools.chain, tmp_dict.values())))

        for entity_group_list in final_grouped_list:

            # Get the unique number of entities per list
            _entity_count = len(
                set(
                    [
                        prediction_input["entity_group"]
                        for prediction_input in entity_group_list
                    ]
                )
            )

            if entity_group_list:
                if len(entity_group_list) > 1:

                    # Get the tag name
                    tag_name = str(entity_group_list[0]["entity_group"][-3:])

                    # Join the entities
                    entity_value = " ".join(
                        [
                            prediction_input["word"]
                            for prediction_input in entity_group_list
                        ]
                    )

                    # Remove duplicate names
                    _temp_entities = entity_value.split()
                    entity_value = " ".join(
                        sorted(set(_temp_entities), key=_temp_entities.index)
                    )

                    # Compute the average of confidence scores
                    mean_score = np.mean(
                        [
                            prediction_input["score"]
                            for prediction_input in entity_group_list
                        ]
                    )

                    # Frame the entities and ensure name is atleast has more than 1 character
                    if len(entity_value) > 1:
                        final_prediction_list.append(
                            RecordDataResponse(
                                entity_group=tag_name,
                                score=mean_score,
                                word=entity_value,
                            )
                        )
                else:
                    [
                        final_prediction_list.append(
                            RecordDataResponse(
                                entity_group=entity_group["entity_group"][-3:],
                                score=entity_group["score"],
                                word=entity_group["word"],
                            )
                        )
                        for entity_group in entity_group_list if len(re.sub(r"(?i)[^-0-9a-z\\s.,]+", "", entity_group["word"])) > 1
                    ]

        # Sort the by the list by confidence score and return in descending order
        return sorted(final_prediction_list, key=lambda x: x.score, reverse=True)
`

