def pretrained_config(cls):
    class Wrapper(transformers.PretrainedConfig):
        pass
    Wrapper.__name__ = cls.__name__
    if hasattr(cls, "model_type"):
        setattr(Wrapper, "model_type", cls.model_type)
    def initializer(self, **kwargs):
        for key, value in vars(cls).items():
            if key.startswith("__") or key == "model_type":
                continue
            value = kwargs.pop(key, value)
            setattr(self, key, value)
        transformers.PretrainedConfig.__init__(self, **kwargs)
    Wrapper.__init__ = initializer
    return Wrapper


